INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-57-v1', 'mbpp-57', 1, 'Find max num', 'Sorting & searching', 'Medium', 'Write a python function to find the largest number that can be formed with the given list of digits.

Example: find_Max_Num([1, 2, 3]) returns 321.', 'def find_Max_Num(arr):
    pass
', 'def find_Max_Num(arr) : 
    n = len(arr)
