INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-71-v1', 'mbpp-71', 1, 'Comb sort', 'Sorting & searching', 'Hard', 'Write a function to sort a list of elements.

Example: comb_sort([5, 15, 37, 25, 79]) returns [5, 15, 25, 37, 79].', 'def comb_sort(nums):
    pass
', 'def comb_sort(nums):
    shrink_fact = 1.3
    gaps = len(nums)
    swapped = True
    i = 0
    while gaps > 1 or swapped:
        gaps = int(float(gaps) / shrink_fact)
        swapped = False
        i = 0
        while gaps + i < len(nums):
            if nums[i] > nums[i+gaps]:
                nums[i], nums[i+gaps] = nums[i+gaps], nums[i]
                swapped = True
            i += 1
    return nums
', 'Confirm the example: comb_sort([5, 15, 37, 25, 79]) returns [5, 15, 25, 37, 79]. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'comb_sort', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
