INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-103-v1', 'mbpp-103', 1, 'Eulerian num', 'Math & number theory', 'Easy', 'Write a function to find the Eulerian number a(n, m).

Example: eulerian_num(3, 1) returns 4.', 'def eulerian_num(n, m):
    pass
', 'def eulerian_num(n, m): 
	if (m >= n or n == 0): 
		return 0 
	if (m == 0): 
		return 1 
	return ((n - m) * eulerian_num(n - 1, m - 1) +(m + 1) * eulerian_num(n - 1, m))
', 'Confirm the example: eulerian_num(3, 1) returns 4. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'eulerian_num', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
