INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-125-v1', 'mbpp-125', 1, 'Find length', 'Bit manipulation', 'Medium', 'Write a function to find the maximum difference between the number of 0s and number of 1s in any sub-string of the given binary string.

Example: find_length(''11000010001'') returns 6.', 'def find_length(string):
    pass
', 'def find_length(string): 
	n = len(string)
	current_sum = 0
	max_sum = 0
	for i in range(n): 
		current_sum += (1 if string[i] == ''0'' else -1) 
		if current_sum < 0: 
			current_sum = 0
		max_sum = max(current_sum, max_sum) 
	return max_sum if max_sum else 0
', 'Confirm the example: find_length(''11000010001'') returns 6. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'find_length', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
