INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-256-v1', 'mbpp-256', 1, 'Count primes nums', 'Math & number theory', 'Medium', 'Write a python function that takes in a non-negative number and returns the number of prime numbers less than the given non-negative number.

Example: count_Primes_nums(5) returns 2.', 'def count_Primes_nums(n):
    pass
', 'def count_Primes_nums(n):
    ctr = 0
    for num in range(n):
        if num <= 1:
            continue
        for i in range(2,num):
            if (num % i) == 0:
                break
        else:
            ctr += 1
    return ctr
', 'Confirm the example: count_Primes_nums(5) returns 2. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'count_Primes_nums', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
