INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-283-v1', 'mbpp-283', 1, 'Validate', 'Hash maps & sets', 'Medium', 'Write a python function takes in an integer and check whether the frequency of each digit in the integer is less than or equal to the digit itself.

Example: validate(1234) returns True.', 'def validate(n):
    pass
', 'def validate(n): 
    for i in range(10): 
        temp = n;  
        count = 0; 
        while (temp): 
            if (temp % 10 == i): 
                count+=1;  
            if (count > i): 
                return False
