INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-408-v1', 'mbpp-408', 1, 'K smallest pairs', 'Sorting & searching', 'Medium', 'Write a function to find k number of smallest pairs which consist of one element from the first array and one element from the second array.

Example: k_smallest_pairs([1, 3, 7], [2, 4, 6], 2) returns [[1, 2], [1, 4]].', 'def k_smallest_pairs(nums1, nums2, k):
    pass
', 'import heapq
def k_smallest_pairs(nums1, nums2, k):
   queue = []
   def push(i, j):
       if i < len(nums1) and j < len(nums2):
           heapq.heappush(queue, [nums1[i] + nums2[j], i, j])
   push(0, 0)
   pairs = []
   while queue and len(pairs) < k:
       _, i, j = heapq.heappop(queue)
       pairs.append([nums1[i], nums2[j]])
       push(i, j + 1)
       if j == 0:
           push(i + 1, 0)
   return pairs
', 'Confirm the example: k_smallest_pairs([1, 3, 7], [2, 4, 6], 2) returns [[1, 2], [1, 4]]. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'k_smallest_pairs', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
