INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-428-v1', 'mbpp-428', 1, 'Shell sort', 'Sorting & searching', 'Hard', 'Write a function to sort the given array by using shell sort.

Example: shell_sort([12, 23, 4, 5, 3, 2, 12, 81, 56, 95]) returns [2, 3, 4, 5, 12, 12, 23, 56, 81, 95].', 'def shell_sort(my_list):
    pass
', 'def shell_sort(my_list):
    gap = len(my_list) // 2
    while gap > 0:
        for i in range(gap, len(my_list)):
            current_item = my_list[i]
            j = i
            while j >= gap and my_list[j - gap] > current_item:
                my_list[j] = my_list[j - gap]
                j -= gap
            my_list[j] = current_item
        gap //= 2

    return my_list
', 'Confirm the example: shell_sort([12, 23, 4, 5, 3, 2, 12, 81, 56, 95]) returns [2, 3, 4, 5, 12, 12, 23, 56, 81, 95]. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'shell_sort', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
