INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-453-v1', 'mbpp-453', 1, 'Sumof factors', 'Math & number theory', 'Hard', 'Write a python function to find the sum of even factors of a number.

Example: sumofFactors(18) returns 26.', 'def sumofFactors(n):
    pass
', 'import math 
def sumofFactors(n) : 
    if (n % 2 != 0) : 
        return 0
    res = 1
    for i in range(2, (int)(math.sqrt(n)) + 1) :    
        count = 0
        curr_sum = 1
        curr_term = 1
        while (n % i == 0) : 
            count= count + 1
            n = n // i 
            if (i == 2 and count == 1) : 
                curr_sum = 0
            curr_term = curr_term * i 
            curr_sum = curr_sum + curr_term 
        res = res * curr_sum  
    if (n >= 2) : 
        res = res * (1 + n) 
    return res
', 'Confirm the example: sumofFactors(18) returns 26. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'sumofFactors', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
