INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-559-v1', 'mbpp-559', 1, 'Max sub array sum', 'Sorting & searching', 'Medium', 'Write a function to find the sum of the largest contiguous sublist in the given list.

Example: max_sub_array_sum([-2, -3, 4, -1, -2, 1, 5, -3], 8) returns 7.', 'def max_sub_array_sum(a, size):
    pass
', 'def max_sub_array_sum(a, size):
  max_so_far = 0
  max_ending_here = 0
  for i in range(0, size):
    max_ending_here = max_ending_here + a[i]
    if max_ending_here < 0:
      max_ending_here = 0
    elif (max_so_far < max_ending_here):
      max_so_far = max_ending_here
  return max_so_far
', 'Confirm the example: max_sub_array_sum([-2, -3, 4, -1, -2, 1, 5, -3], 8) returns 7. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'max_sub_array_sum', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
