INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-595-v1', 'mbpp-595', 1, 'Min swaps', 'Bit manipulation', 'Medium', 'Write a python function to count minimum number of swaps required to convert one binary number represented as a string to another.

Example: min_Swaps(''1101'', ''1110'') returns 1.', 'def min_Swaps(str1, str2):
    pass
', 'def min_Swaps(str1,str2) : 
    count = 0
    for i in range(len(str1)) :  
