INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-603-v1', 'mbpp-603', 1, 'Get ludic', 'Math & number theory', 'Hard', 'Write a function to get all lucid numbers smaller than or equal to a given integer.

Example: get_ludic(10) returns [1, 2, 3, 5, 7].', 'def get_ludic(n):
    pass
', 'def get_ludic(n):
	ludics = []
	for i in range(1, n + 1):
		ludics.append(i)
	index = 1
	while(index != len(ludics)):
		first_ludic = ludics[index]
		remove_index = index + first_ludic
		while(remove_index < len(ludics)):
			ludics.remove(ludics[remove_index])
			remove_index = remove_index + first_ludic - 1
		index += 1
	return ludics
', 'Confirm the example: get_ludic(10) returns [1, 2, 3, 5, 7]. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'get_ludic', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
