INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-638-v1', 'mbpp-638', 1, 'Wind chill', 'Math & number theory', 'Easy', 'Write a function to calculate the wind chill index rounded to the next integer given the wind velocity in km/h and a temperature in celsius.

Example: wind_chill(120, 35) returns 40.', 'def wind_chill(v, t):
    pass
