INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-734-v1', 'mbpp-734', 1, 'Sum of subarray prod', 'Math & number theory', 'Medium', 'Write a python function to find sum of products of all possible sublists of a given list. https://www.geeksforgeeks.org/sum-of-products-of-all-possible-subarrays/

Example: sum_Of_Subarray_Prod([1, 2, 3]) returns 20.', 'def sum_Of_Subarray_Prod(arr):
    pass
', 'def sum_Of_Subarray_Prod(arr):
    ans = 0
    res = 0
    i = len(arr) - 1
    while (i >= 0):
        incr = arr[i]*(1 + res)
        ans += incr
        res = incr
        i -= 1
    return (ans)
', 'Confirm the example: sum_Of_Subarray_Prod([1, 2, 3]) returns 20. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'sum_Of_Subarray_Prod', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
