INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-755-v1', 'mbpp-755', 1, 'Second smallest', 'Sorting & searching', 'Easy', 'Write a function to find the second smallest number in a list.

Example: second_smallest([1, 2, -8, -2, 0, -2]) returns -2.', 'def second_smallest(numbers):
    pass
', 'def second_smallest(numbers):
