INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('mbpp-771-v1', 'mbpp-771', 1, 'Check expression', 'Fundamentals', 'Medium', 'Write a function to check if the given expression is balanced or not. https://www.geeksforgeeks.org/check-for-balanced-parentheses-in-an-expression/

Example: check_expression(''{()}[{}]'') returns True.', 'def check_expression(exp):
    pass
', 'from collections import deque
def check_expression(exp):
    if len(exp) & 1:
        return False
    stack = deque()
    for ch in exp:
        if ch == ''('' or ch == ''{'' or ch == ''['':
            stack.append(ch)
        if ch == '')'' or ch == ''}'' or ch == '']'':
            if not stack:
                return False
            top = stack.pop()
            if (top == ''('' and ch != '')'') or (top == ''{'' and ch != ''}'' or (top == ''['' and ch != '']'')):
                return False
    return not stack
', 'Confirm the example: check_expression(''{()}[{}]'') returns True. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'check_expression', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
