INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-1-v1', 'humaneval-1', 1, 'Separate paren groups', 'Strings', 'Hard', 'Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
separate those group into separate strings and return the list of those.
Separate groups are balanced (each open brace is properly closed) and not nested within each other
Ignore any spaces in the input string.
>>> separate_paren_groups(''( ) (( )) (( )( ))'')
[''()'', ''(())'', ''(()())'']', 'from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups(''( ) (( )) (( )( ))'')
    [''()'', ''(())'', ''(()())'']
    """
    pass
', 'from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups(''( ) (( )) (( )( ))'')
    [''()'', ''(())'', ''(()())'']
    """
    result = []
    current_string = []
    current_depth = 0

    for c in paren_string:
        if c == ''('':
            current_depth += 1
            current_string.append(c)
        elif c == '')'':
            current_depth -= 1
            current_string.append(c)

            if current_depth == 0:
                result.append(''''.join(current_string))
                current_string.clear()

    return result
', 'Confirm the example: separate_paren_groups(''(()()) ((())) () ((())()())'') returns [''(()())'', ''((()))'', ''()'', ''((())()())'']. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'separate_paren_groups', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
