INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-3-v1', 'humaneval-3', 1, 'Below zero', 'Arrays & lists', 'Medium', 'You''re given a list of deposit and withdrawal operations on a bank account that starts with
