INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-46-v1', 'humaneval-46', 1, 'Fib4', 'Math & number theory', 'Medium', 'The Fib4 number sequence is a sequence similar to the Fibbonacci sequnece that''s defined as follows:
fib4(0) -> 0
