INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-58-v1', 'humaneval-58', 1, 'Common', 'Hash maps & sets', 'Medium', 'Return sorted unique common elements for two lists.
>>> common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121])
