def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def is_prime(k):
        if k < 2:
            return False
        for i in range(2, k - 1):
            if k % i == 0:
                return False
        return True
    largest = 1
    for j in range(2, n + 1):
        if n % j == 0 and is_prime(j):
            largest = max(largest, j)
    return largest
', 'Confirm the example: largest_prime_factor(15) returns 5. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'largest_prime_factor', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
