def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length is a prime number or False otherwise
    Examples
    prime_length(''Hello'') == True
    prime_length(''abcdcba'') == True
    prime_length(''kittens'') == True
    prime_length(''orange'') == False
    """
    pass
', '
def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length is a prime number or False otherwise
    Examples
    prime_length(''Hello'') == True
    prime_length(''abcdcba'') == True
    prime_length(''kittens'') == True
    prime_length(''orange'') == False
    """
    l = len(string)
    if l == 0 or l == 1:
        return False
    for i in range(2, l):
        if l % i == 0:
            return False
    return True
', 'Confirm the example: prime_length(''Hello'') returns True. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'prime_length', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
