INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-88-v1', 'humaneval-88', 1, 'Sort array', 'Sorting & searching', 'Easy', 'Given an array of non-negative integers, return a copy of the given array after sorting,
