INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-89-v1', 'humaneval-89', 1, 'Encrypt', 'Strings', 'Medium', 'Create a function encrypt that takes a string as an argument and
returns a string encrypted with the alphabet being rotated. 
The alphabet should be rotated in a manner such that the letters 
shift down by two multiplied to two places.
For example:
encrypt(''hi'') returns ''lm''
encrypt(''asdfghjkl'') returns ''ewhjklnop''
encrypt(''gf'') returns ''kj''
encrypt(''et'') returns ''ix''', '
def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    For example:
    encrypt(''hi'') returns ''lm''
    encrypt(''asdfghjkl'') returns ''ewhjklnop''
    encrypt(''gf'') returns ''kj''
    encrypt(''et'') returns ''ix''
    """
    pass
', '
def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    For example:
    encrypt(''hi'') returns ''lm''
    encrypt(''asdfghjkl'') returns ''ewhjklnop''
    encrypt(''gf'') returns ''kj''
    encrypt(''et'') returns ''ix''
    """
    d = ''abcdefghijklmnopqrstuvwxyz''
    out = ''''
    for c in s:
        if c in d:
            out += d[(d.index(c)+2*2) % 26]
        else:
            out += c
    return out
', 'Confirm the example: encrypt(''hi'') returns ''lm''. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'encrypt', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
