INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-136-v1', 'humaneval-136', 1, 'Largest smallest integers', 'Sorting & searching', 'Easy', 'Create a function that returns a tuple (a, b), where ''a'' is
the largest of negative integers, and ''b'' is the smallest
of positive integers in a list.
If there is no negative or positive integers, return them as None.

Examples:
largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
largest_smallest_integers([]) == (None, None)
largest_smallest_integers([0]) == (None, None)', '
def largest_smallest_integers(lst):
    ''''''
    Create a function that returns a tuple (a, b), where ''a'' is
    the largest of negative integers, and ''b'' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    ''''''
    pass
', '
def largest_smallest_integers(lst):
    ''''''
    Create a function that returns a tuple (a, b), where ''a'' is
    the largest of negative integers, and ''b'' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    ''''''
    smallest = list(filter(lambda x: x < 0, lst))
    largest = list(filter(lambda x: x > 0, lst))
    return (max(smallest) if smallest else None, min(largest) if largest else None)
', 'Confirm the example: largest_smallest_integers([2, 4, 1, 3, 5, 7]) returns [None, 1]. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'largest_smallest_integers', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
