INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-141-v1', 'humaneval-141', 1, 'File name check', 'Strings', 'Hard', 'Create a function which takes a string representing a file''s name, and returns
''Yes'' if the the file''s name is valid, and returns ''No'' otherwise.
A file''s name is considered to be valid if and only if all the following conditions 
are met:
- There should not be more than three digits (''0''-''9'') in the file''s name.
- The file''s name contains exactly one dot ''.''
- The substring before the dot should not be empty, and it starts with a letter from 
the latin alphapet (''a''-''z'' and ''A''-''Z'').
- The substring after the dot should be one of these: [''txt'', ''exe'', ''dll'']
Examples:
file_name_check("example.txt") # => ''Yes''
file_name_check("1example.dll") # => ''No'' (the name should start with a latin alphapet letter)', '
def file_name_check(file_name):
    """Create a function which takes a string representing a file''s name, and returns
    ''Yes'' if the the file''s name is valid, and returns ''No'' otherwise.
    A file''s name is considered to be valid if and only if all the following conditions 
    are met:
    - There should not be more than three digits (''0''-''9'') in the file''s name.
    - The file''s name contains exactly one dot ''.''
    - The substring before the dot should not be empty, and it starts with a letter from 
    the latin alphapet (''a''-''z'' and ''A''-''Z'').
    - The substring after the dot should be one of these: [''txt'', ''exe'', ''dll'']
    Examples:
    file_name_check("example.txt") # => ''Yes''
    file_name_check("1example.dll") # => ''No'' (the name should start with a latin alphapet letter)
    """
    pass
', '
def file_name_check(file_name):
    """Create a function which takes a string representing a file''s name, and returns
    ''Yes'' if the the file''s name is valid, and returns ''No'' otherwise.
    A file''s name is considered to be valid if and only if all the following conditions 
    are met:
    - There should not be more than three digits (''0''-''9'') in the file''s name.
    - The file''s name contains exactly one dot ''.''
    - The substring before the dot should not be empty, and it starts with a letter from 
    the latin alphapet (''a''-''z'' and ''A''-''Z'').
    - The substring after the dot should be one of these: [''txt'', ''exe'', ''dll'']
    Examples:
    file_name_check("example.txt") # => ''Yes''
    file_name_check("1example.dll") # => ''No'' (the name should start with a latin alphapet letter)
    """
    suf = [''txt'', ''exe'', ''dll'']
    lst = file_name.split(sep=''.'')
    if len(lst) != 2:
        return ''No''
    if not lst[1] in suf:
        return ''No''
    if len(lst[0]) == 0:
        return ''No''
    if not lst[0][0].isalpha():
        return ''No''
    t = len([x for x in lst[0] if x.isdigit()])
    if t > 3:
        return ''No''
    return ''Yes''
', 'Confirm the example: file_name_check(''example.txt'') returns ''Yes''. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'file_name_check', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
