INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-147-v1', 'humaneval-147', 1, 'Get max triples', 'Math & number theory', 'Hard', 'You are given a positive integer n. You have to create an integer array a of length n.
