INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-148-v1', 'humaneval-148', 1, 'Bf', 'Strings', 'Medium', 'There are eight planets in our solar system: the closerst to the Sun 
