INSERT INTO problems (id, problem_family_id, revision, title, topic, difficulty, prompt, starter_code, reference_solution, clarification_guidance, help_guidance, entry_point, test_contract, is_sample) VALUES ('humaneval-162-v1', 'humaneval-162', 1, 'String to md5', 'Strings', 'Easy', 'Given a string ''text'', return its md5 hash equivalent string.
If ''text'' is an empty string, return None.

>>> string_to_md5(''Hello world'') == ''3e25960a79dbc69b674cd4ec67a72c62''', '
def string_to_md5(text):
    """
    Given a string ''text'', return its md5 hash equivalent string.
    If ''text'' is an empty string, return None.

    >>> string_to_md5(''Hello world'') == ''3e25960a79dbc69b674cd4ec67a72c62''
    """
    pass
', '
def string_to_md5(text):
    """
    Given a string ''text'', return its md5 hash equivalent string.
    If ''text'' is an empty string, return None.

    >>> string_to_md5(''Hello world'') == ''3e25960a79dbc69b674cd4ec67a72c62''
    """
    import hashlib
    return hashlib.md5(text.encode(''ascii'')).hexdigest() if text else None
', 'Confirm the example: string_to_md5(''Hello world'') returns ''3e25960a79dbc69b674cd4ec67a72c62''. Ask about empty, repeated, or boundary inputs before coding.', 'Ask the candidate to trace the first visible example by hand and state the rule they applied before changing code.', 'string_to_md5', '{"arguments":"positional JSON arguments","return":"JSON-serializable return value","comparison":"exact JSON equality"}'::jsonb, false);
